import '../ai/memory/memory.dart';
import '../ai/memory/utils/async_lock.dart';
import 'memory_store.dart';
class InMemoryStore implements MemoryStore { final Map<String, Memory> _store = {}; final AsyncLock _lock = AsyncLock(); @override Future<Memory> save(Memory m) { return _lock.synchronized(() async { _store[m.id] = m; return m; }); } @override Future<Memory?> getById(String id) { return _lock.synchronized(() async => _store[id]); } @override Future<List<Memory>> getAll() { return _lock.synchronized(() async => _store.values.toList()); } @override Future<List<Memory>> search(String query) { return _lock.synchronized(() async { if (query.isEmpty) return _store.values.toList(); final lower = query.toLowerCase(); return _store.values.where((m) => m.content.toLowerCase().contains(lower)).toList(); }); } @override Future<List<Memory>> getByConversation(String conversationId) { return _lock.synchronized(() async { final list = _store.values.where((m) => m.conversationId == conversationId).toList()..sort((a, b) => a.createdAt.compareTo(b.createdAt)); return list; }); } @override Future<void> delete(String id) { return _lock.synchronized(() async { _store.remove(id); }); } @override Future<void> deleteConversation(String conversationId) { return _lock.synchronized(() async { _store.removeWhere((_, m) => m.conversationId == conversationId); }); } @override Future<void> clear() { return _lock.synchronized(() async { _store.clear(); }); } @override Future<int> count() { return _lock.synchronized(() async => _store.length); } }
